package com.android.tools.lint.checks

import com.android.SdkConstants
import com.android.resources.ResourceFolderType
import com.android.tools.lint.detector.api.*
import org.w3c.dom.Attr
import org.w3c.dom.Element
import java.util.*

class ResourceCycleDetector : Detector(), XmlScanner {

    private val graph = mutableMapOf<Node, MutableSet<Node>>()
    private val fileMap = mutableMapOf<Node, XmlContext>()

    override fun beforeCheckRootProject(context: Context) {
        graph.clear()
        fileMap.clear()
    }

    override fun appliesTo(folderType: ResourceFolderType): Boolean = true

    override fun getApplicableElements(): Collection<String>? = ALL

    override fun visitElement(context: XmlContext, element: Element) {
        val current = resourceNodeFor(context) ?: return
        fileMap[current] = context
        val refs = mutableSetOf<Node>()
        // style parent
        if (element.tagName == SdkConstants.TAG_STYLE) {
            val parentAttr = element.getAttributeNode(SdkConstants.ATTR_PARENT)
            if (parentAttr != null) {
                parseReference(parentAttr.value, ResourceFolderType.VALUES)?.let { refs.add(it) }
            } else {
                // implicit parent from name with dot
                val nameAttr = element.getAttributeNode(SdkConstants.ATTR_NAME)
                if (nameAttr != null) {
                    val name = nameAttr.value
                    val dotIndex = name.lastIndexOf('.')
                    if (dotIndex > 0) {
                        refs.add(Node(ResourceFolderType.VALUES, name.substring(0, dotIndex)))
                    }
                }
            }
        }
        // include layout
        if (element.tagName == SdkConstants.TAG_INCLUDE || element.tagName == SdkConstants.TAG_MERGE_INCLUDE) {
            val layoutAttr = element.getAttributeNode(SdkConstants.ATTR_LAYOUT)
            if (layoutAttr != null) {
                parseReference(layoutAttr.value, ResourceFolderType.LAYOUT)?.let { refs.add(it) }
            }
        }
        // all attributes resource references
        for (i in 0 until element.attributes.length) {
            val attr = element.attributes.item(i) as Attr
            parseReference(attr.value, null)?.let { refs.add(it) }
        }
        // children text? not needed
        if (refs.isNotEmpty()) {
            graph.getOrPut(current) { mutableSetOf() }.addAll(refs)
        }
    }

    override fun afterCheckRootProject(context: Context) {
        findCycles(context)
    }

    private fun findCycles(context: Context) {
        val visited = mutableSetOf<Node>()
        val stack = LinkedHashSet<Node>()
        val reported = mutableSetOf<String>()
        for (node in graph.keys) {
            if (node !in visited) {
                dfs(node, visited, stack, reported, context)
            }
        }
    }

    private fun dfs(
        node: Node,
        visited: MutableSet<Node>,
        stack: LinkedHashSet<Node>,
        reported: MutableSet<String>,
        context: Context
    ) {
        visited += node
        stack += node
        for (next in graph[node].orEmpty()) {
            if (next in stack) {
                // cycle found
                val cycle = stack.dropWhile { it != next } + next
                val key = cycle.sortedBy { it.toString() }.joinToString()
                if (reported.add(key)) {
                    reportCycle(cycle, context)
                }
            } else if (next !in visited) {
                dfs(next, visited, stack, reported, context)
            }
        }
        stack -= node
    }

    private fun reportCycle(cycle: List<Node>, context: Context) {
        val sb = StringBuilder("Cycle in resource definitions: ")
        for ((i, node) in cycle.withIndex()) {
            if (i > 0) sb.append(" -> ")
            sb.append(node.type.getName()).append("/").append(node.name)
        }
        val message = sb.toString()
        // Report on each node in cycle
        for (node in cycle) {
            val xmlContext = fileMap[node] ?: continue
            xmlContext.report(ISSUE, xmlContext.getLocation(xmlContext.document.documentElement), message)
        }
    }

    private fun resourceNodeFor(context: XmlContext): Node? {
        val folderType = context.resourceFolderType ?: return null
        val name = context.file.nameWithoutExtension ?: return null
        return Node(folderType, name)
    }

    private fun parseReference(value: String, defaultType: ResourceFolderType?): Node? {
        if (value.isBlank()) return null
        val m = REF_PATTERN.matchEntire(value.trim()) ?: return null
        val typeName = m.groupValues[2].takeIf { it.isNotEmpty() } ?: defaultType?.getName() ?: return null
        val type = ResourceFolderType.getFolderType(typeName) ?: return null
        val name = m.groupValues[3]
        if (name.isEmpty() || name == "+") return null
        return Node(type, name)
    }

    private data class Node(val type: ResourceFolderType, val name: String)

    companion object {
        @JvmField
        val ISSUE = Issue.create(
            id = "ResourceCycle",
            briefDescription = "Cycle in resource definitions",
            explanation = """
                There should be no cycles in resource definitions as this can lead to runtime exceptions.
            """,
            category = Category.CORRECTNESS,
            priority = 9,
            severity = Severity.FATAL,
            implementation = Implementation(ResourceCycleDetector::class.java, Scope.RESOURCE_FILE_SCOPE)
        )

        private val REF_PATTERN = Regex("""^@(?:([a-zA-Z0-9_.]+):)?([a-zA-Z]+)/([a-zA-Z0-9_.]+)$""")
    }
}
```

